public:
  class scheduler {
    class schedule_task {
    public:
      template <
          template <typename...>
          class Variant,
          template <typename...>
          class Tuple>
      using value_types = Variant<Tuple<>>;

      template <template <typename...> class Variant>
      using error_types = Variant<>;

      static constexpr bool sends_done = true;

      static constexpr blocking_kind blocking = blocking_kind::never;

